-- Reconcile the seeded order state, Escrow amount and common 5% commission policy.
UPDATE rental_orders
SET locked_amount = CASE WHEN status IN ('PENDING_PROVIDER_ACCEPTANCE','PENDING_START_CONFIRMATION','PROCESSING','PENDING_CUSTOMER_ACCEPTANCE','PENDING_PAYMENT_OTP','CANCELLATION_REQUESTED_BY_CUSTOMER','CANCELLATION_COMPENSATION_PENDING_CUSTOMER') THEN total ELSE 0 END,
    provider_accepted = CASE WHEN status IN ('PENDING_START_CONFIRMATION','PROCESSING','PENDING_CUSTOMER_ACCEPTANCE','PENDING_PAYMENT_OTP','CANCELLATION_REQUESTED_BY_CUSTOMER','CANCELLATION_COMPENSATION_PENDING_CUSTOMER','COMPLETED') THEN TRUE ELSE FALSE END,
    customer_started = CASE WHEN status IN ('PROCESSING','PENDING_CUSTOMER_ACCEPTANCE','PENDING_PAYMENT_OTP','CANCELLATION_REQUESTED_BY_CUSTOMER','CANCELLATION_COMPENSATION_PENDING_CUSTOMER','COMPLETED') THEN TRUE ELSE FALSE END,
    provider_started = CASE WHEN status IN ('PROCESSING','PENDING_CUSTOMER_ACCEPTANCE','PENDING_PAYMENT_OTP','CANCELLATION_REQUESTED_BY_CUSTOMER','CANCELLATION_COMPENSATION_PENDING_CUSTOMER','COMPLETED') THEN TRUE ELSE FALSE END,
    provider_completed = CASE WHEN status IN ('PENDING_CUSTOMER_ACCEPTANCE','PENDING_PAYMENT_OTP','COMPLETED') THEN TRUE ELSE FALSE END,
    customer_accepted_completion = CASE WHEN status IN ('PENDING_PAYMENT_OTP','COMPLETED') THEN TRUE ELSE FALSE END,
    settled_at = CASE WHEN status='COMPLETED' THEN COALESCE(settled_at, completed_at, created_at) ELSE settled_at END,
    platform_fee_amount = CASE WHEN status='COMPLETED' THEN ROUND(total * 0.05, 2)
                               WHEN status='CANCELLED' AND settled_at IS NOT NULL THEN ROUND(COALESCE(cancellation_compensation,0) * 0.05, 2)
                               ELSE platform_fee_amount END,
    provider_net_amount = CASE WHEN status='COMPLETED' THEN total - ROUND(total * 0.05, 2)
                               WHEN status='CANCELLED' AND settled_at IS NOT NULL THEN COALESCE(cancellation_compensation,0) - ROUND(COALESCE(cancellation_compensation,0) * 0.05, 2)
                               ELSE provider_net_amount END;

-- 18. Wallet/Escrow seed rows for all expanded demo users. Demo credits only; no real payment.
-- Primary Customer/Provider wallets and their ledger were created in DemoDataConfig; add only missing wallets.
SELECT u.id,
       CASE WHEN u.role='PROVIDER' THEN COALESCE((SELECT SUM(o.provider_net_amount) FROM rental_orders o WHERE o.provider_id=u.id AND o.status='COMPLETED' AND o.settled_at IS NOT NULL),0)
            ELSE 0 END,
       COALESCE((SELECT SUM(o.total) FROM rental_orders o WHERE o.customer_id=u.id AND o.locked_amount > 0),0)
FROM users u
LEFT JOIN user_wallets existing ON existing.user_id=u.id
WHERE existing.id IS NULL;

-- One receipt per synthetic completed project. IDs 6+ are the supplemental seed orders.
SELECT w.id, o.id, 'SETTLEMENT_IN', o.provider_net_amount,
       (SELECT COALESCE(SUM(o2.provider_net_amount),0) FROM rental_orders o2
        WHERE o2.provider_id=o.provider_id AND o2.status='COMPLETED' AND o2.settled_at IS NOT NULL AND o2.id <= o.id),
       0, CONCAT('Tiền thực nhận demo từ DH', o.id, ' sau phí sàn 5% - ', COALESCE(b.service_name, 'Dịch vụ')),
       COALESCE(o.completed_at, o.created_at)
FROM rental_orders o
JOIN user_wallets w ON w.user_id=o.provider_id
LEFT JOIN bookings b ON b.id=o.booking_id
WHERE o.id >= 6 AND o.status='COMPLETED' AND o.settled_at IS NOT NULL AND o.provider_net_amount IS NOT NULL AND o.provider_id IS NOT NULL;
